package connector_test

// generated_test.go — unit coverage for connector.IsGenerated (ADR-021 §2 /
// TI-5, reworked per critic F4): the "Code generated ... DO NOT EDIT"
// header heuristic that lets fathom tag generated files instead of silently
// counting them as hand-written code. Go files scan to the package clause
// (the actual Go convention); other languages use a small window plus a
// comment-token requirement so QUOTING the marker (markdown, strings) does
// not flag a file.

import (
	"strings"
	"testing"

	"github.com/geoffmilleraz/fathom/internal/connector"
)

func TestIsGenerated_PlainSourceIsNotGenerated(t *testing.T) {
	if connector.IsGenerated("main.go", []byte("package main\n\nfunc main() {}\n")) {
		t.Error("hand-written source misclassified as generated")
	}
}

func TestIsGenerated_Empty(t *testing.T) {
	if connector.IsGenerated("main.go", nil) {
		t.Error("empty content misclassified as generated")
	}
	if connector.IsGenerated("main.go", []byte{}) {
		t.Error("empty slice misclassified as generated")
	}
}

func TestIsGenerated_ProtocGenGo(t *testing.T) {
	src := "// Code generated by protoc-gen-go. DO NOT EDIT.\npackage foo\n"
	if !connector.IsGenerated("foo.pb.go", []byte(src)) {
		t.Error("protoc-gen-go header not detected as generated")
	}
}

func TestIsGenerated_Mockgen(t *testing.T) {
	src := "// Code generated by MockGen. DO NOT EDIT.\npackage mocks\n"
	if !connector.IsGenerated("mocks/mock_store.go", []byte(src)) {
		t.Error("MockGen header not detected as generated")
	}
}

func TestIsGenerated_Stringer(t *testing.T) {
	src := "// Code generated by \"stringer -type=Foo\"; DO NOT EDIT.\npackage foo\n"
	if !connector.IsGenerated("foo_string.go", []byte(src)) {
		t.Error("stringer header not detected as generated")
	}
}

// TestIsGenerated_GoMarkerAfterLicenseHeader is critic probe P11: the Go
// convention places the marker before the PACKAGE CLAUSE, not in the first
// 3 lines — the entire zz_generated ecosystem (k8s deepcopy etc.) carries a
// full Apache license header first, putting the marker at line ~17. A
// 3-line window missed every one of them.
func TestIsGenerated_GoMarkerAfterLicenseHeader(t *testing.T) {
	var b strings.Builder
	b.WriteString("/*\n")
	for i := 0; i < 14; i++ {
		b.WriteString("Licensed under the Apache License, Version 2.0 (the \"License\");\n")
	}
	b.WriteString("*/\n\n")
	b.WriteString("// Code generated by deepcopy-gen. DO NOT EDIT.\n\n")
	b.WriteString("package v1\n")
	if !connector.IsGenerated("zz_generated.deepcopy.go", []byte(b.String())) {
		t.Error("Go marker after a license header (before the package clause) not detected")
	}
}

// TestIsGenerated_GoMarkerAfterPackageClauseIgnored: the convention requires
// the marker BEFORE the package clause; a mention later in the file (e.g. a
// doc comment about generated code) must not flag the file.
func TestIsGenerated_GoMarkerAfterPackageClauseIgnored(t *testing.T) {
	src := "package gen\n\n// Code generated by tool. DO NOT EDIT.\nfunc X() {}\n"
	if connector.IsGenerated("gen.go", []byte(src)) {
		t.Error("marker after the package clause should not flag a Go file")
	}
}

func TestIsGenerated_HashCommentStyle(t *testing.T) {
	// YAML-style comment prefix — the marker line starts with the language's
	// own comment token.
	src := "# Code generated by some-tool. DO NOT EDIT.\nkey: value\n"
	if !connector.IsGenerated("config.yaml", []byte(src)) {
		t.Error("hash-comment generated header not detected in YAML")
	}
}

// TestIsGenerated_MarkdownQuotingMarkerNotGenerated is critic probe P16: a
// markdown document QUOTING the marker (documentation about the convention,
// a fenced code example) is not itself generated — flagging it removed real
// docs from cloc's code counts. Markdown's only honored comment form is an
// HTML comment.
func TestIsGenerated_MarkdownQuotingMarkerNotGenerated(t *testing.T) {
	src := "// Code generated by protoc-gen-go. DO NOT EDIT.\n\nThis doc explains the convention.\n"
	if connector.IsGenerated("docs/codegen.md", []byte(src)) {
		t.Error("markdown quoting the marker misclassified as generated")
	}
	fenced := "```go\n// Code generated by tool. DO NOT EDIT.\n```\n"
	if connector.IsGenerated("docs/example.md", []byte(fenced)) {
		t.Error("fenced code block quoting the marker misclassified as generated")
	}
}

func TestIsGenerated_MarkdownHTMLCommentMarker(t *testing.T) {
	// Tools that generate markdown emit the marker as an HTML comment — the
	// one comment form markdown has.
	src := "<!-- Code generated by docs-gen. DO NOT EDIT. -->\n# API Reference\n"
	if !connector.IsGenerated("docs/api.md", []byte(src)) {
		t.Error("HTML-comment marker in markdown not detected")
	}
}

func TestIsGenerated_NonGoBeyondScanWindow(t *testing.T) {
	// Non-Go languages keep a small window; a marker deep in the file no
	// longer counts.
	src := strings.Repeat("key: value\n", 10) + "# Code generated by tool. DO NOT EDIT.\n"
	if connector.IsGenerated("config.yaml", []byte(src)) {
		t.Error("marker beyond the non-Go scan window should not flip the classification")
	}
}

func TestIsGenerated_YAMLMarkerNotOnCommentLineIgnored(t *testing.T) {
	// The marker text inside a VALUE (not a comment line) is quoting, not a
	// header.
	src := "description: \"Code generated by tool. DO NOT EDIT.\"\nkey: value\n"
	if connector.IsGenerated("config.yaml", []byte(src)) {
		t.Error("marker inside a YAML value misclassified as generated")
	}
}
